import json, urllib.parse, urllib.request
BASE = 'https://api.openalex.org/works'
params = {'filter': 'is_retracted:true', 'per-page': '200',
          'select': 'doi,publication_year,cited_by_count,counts_by_year',
          'mailto': 'you@example.com', 'cursor': '*'}
while params['cursor']:
    url = BASE + '?' + urllib.parse.urlencode(params)
    page = json.load(urllib.request.urlopen(url))
    for w in page['results']:
        yearly = {c['year']: c['cited_by_count'] for c in w['counts_by_year']}
        print(w['doi'], w['cited_by_count'], yearly)
    params['cursor'] = page['meta']['next_cursor']
